export type ArrowLine = "solid" | "dashed"
export type ArrowHead = "filled" | "open" | "cross" | "none"
export type NotePlacement = "left" | "right" | "over"

export interface SeqParticipant {
  id: string
  label: string
  /** `actor` keyword renders a person glyph instead of a plain box. */
  actor: boolean
  boxId?: string
}

export interface SeqBox {
  id: string
  label: string
  participantIds: string[]
}

export interface SeqMessage {
  kind: "message"
  index: number
  from: string
  to: string
  text: string
  line: ArrowLine
  head: ArrowHead
  self: boolean
  /** `+` suffix: activate the target after this message. */
  activateTarget: boolean
  /** `-` suffix: deactivate the source after this message. */
  deactivateSource: boolean
}

export interface SeqNote {
  kind: "note"
  index: number
  placement: NotePlacement
  participantIds: string[]
  text: string
}

export interface SeqActivation {
  kind: "activate" | "deactivate"
  index: number
  participantId: string
}

export type SeqEvent = SeqMessage | SeqNote | SeqActivation

export interface SeqModel {
  title?: string
  participants: SeqParticipant[]
  boxes: SeqBox[]
  events: SeqEvent[]
}

export interface SequenceLayoutOptions {
  /** Horizontal distance between lifeline centers. */
  columnGap?: number
  /** Vertical distance between consecutive messages. */
  messageGap?: number
  /** Repeat the participant boxes at the bottom of the diagram. */
  showBottomActors?: boolean
}

import type {
  ArrowHead,
  ArrowLine,
  SeqBox,
  SeqEvent,
  SeqModel,
  SeqParticipant,
} from "./types"

interface ArrowSpec {
  token: string
  line: ArrowLine
  head: ArrowHead
}

// Ordered most-specific first so `-->>` wins over `->>`, `-->` over `->`, etc.
const ARROWS: ArrowSpec[] = [
  { token: "-->>", line: "dashed", head: "filled" },
  { token: "->>", line: "solid", head: "filled" },
  { token: "--x", line: "dashed", head: "cross" },
  { token: "-x", line: "solid", head: "cross" },
  { token: "--)", line: "dashed", head: "open" },
  { token: "-)", line: "solid", head: "open" },
  { token: "-->", line: "dashed", head: "none" },
  { token: "->", line: "solid", head: "none" },
]

// Block keywords whose frame we ignore in v1 but whose body we still parse.
const IGNORED_BLOCK_STARTS =
  /^(loop|alt|else|opt|par|and|critical|option|break|rect|autonumber)\b/i

function stripComment(line: string): string {
  const i = line.indexOf("%%")
  return (i === -1 ? line : line.slice(0, i)).trim()
}

function findArrow(text: string): { spec: ArrowSpec; at: number } | null {
  let best: { spec: ArrowSpec; at: number } | null = null
  for (const spec of ARROWS) {
    const at = text.indexOf(spec.token)
    if (at === -1) continue
    // Prefer the earliest arrow; on a tie prefer the more specific (earlier) spec.
    if (!best || at < best.at) best = { spec, at }
  }
  return best
}

/**
 * Parse a Mermaid-flavored sequence diagram into a structured model.
 * Supports: participant/actor, box grouping, sync/async/return arrows,
 * activation (+/- shortcut and activate/deactivate), self-messages and notes.
 */
export function parseSequenceDiagram(input: string): SeqModel {
  const participants: SeqParticipant[] = []
  const byId = new Map<string, SeqParticipant>()
  const boxes: SeqBox[] = []
  const events: SeqEvent[] = []
  let title: string | undefined
  let currentBox: SeqBox | null = null
  let eventIndex = 0

  const ensureParticipant = (raw: string, actor = false): SeqParticipant => {
    const id = raw.trim()
    let p = byId.get(id)
    if (!p) {
      p = { id, label: id, actor }
      byId.set(id, p)
      participants.push(p)
      if (currentBox) {
        p.boxId = currentBox.id
        currentBox.participantIds.push(id)
      }
    }
    return p
  }

  const lines = input.split(/\r?\n/)
  for (const rawLine of lines) {
    const line = stripComment(rawLine)
    if (!line) continue

    const lower = line.toLowerCase()

    if (lower === "sequencediagram") continue

    if (lower.startsWith("title")) {
      const m = line.match(/^title\s*:?\s*(.+)$/i)
      if (m) title = m[1].trim()
      continue
    }

    // box <optional color> <label> ... end
    if (lower.startsWith("box ") || lower === "box") {
      const rest = line.slice(3).trim()
      // Drop a leading color token (e.g. "rgb(...)", "#fff", or a named color).
      const label = rest
        .replace(/^rgba?\([^)]*\)\s*/i, "")
        .replace(/^#[0-9a-f]{3,8}\s+/i, "")
        .replace(/^transparent\s+/i, "")
      currentBox = {
        id: `box-${boxes.length}`,
        label: label.trim(),
        participantIds: [],
      }
      boxes.push(currentBox)
      continue
    }

    if (lower === "end") {
      if (currentBox) currentBox = null
      // otherwise it closes an ignored block (loop/alt/opt/...)
      continue
    }

    if (IGNORED_BLOCK_STARTS.test(line)) continue

    // participant / actor declarations
    const partMatch = line.match(/^(participant|actor)\s+(.+)$/i)
    if (partMatch) {
      const isActor = partMatch[1].toLowerCase() === "actor"
      const body = partMatch[2].trim()
      const asMatch = body.match(/^(.+?)\s+as\s+(.+)$/i)
      if (asMatch) {
        const p = ensureParticipant(asMatch[1], isActor)
        p.label = asMatch[2].trim()
        p.actor = isActor
      } else {
        const p = ensureParticipant(body, isActor)
        p.actor = isActor
      }
      continue
    }

    // notes
    const noteMatch = line.match(
      /^note\s+(right of|left of|over)\s+(.+?)\s*:\s*(.+)$/i,
    )
    if (noteMatch) {
      const placement = noteMatch[1].toLowerCase().startsWith("right")
        ? "right"
        : noteMatch[1].toLowerCase().startsWith("left")
          ? "left"
          : "over"
      const ids = noteMatch[2]
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean)
      ids.forEach((id) => ensureParticipant(id))
      events.push({
        kind: "note",
        index: eventIndex++,
        placement,
        participantIds: ids,
        text: noteMatch[3].trim(),
      })
      continue
    }

    // activate / deactivate
    const actMatch = line.match(/^(activate|deactivate)\s+(.+)$/i)
    if (actMatch) {
      const id = actMatch[2].trim()
      ensureParticipant(id)
      events.push({
        kind: actMatch[1].toLowerCase() as "activate" | "deactivate",
        index: eventIndex++,
        participantId: id,
      })
      continue
    }

    // messages
    const arrow = findArrow(line)
    if (arrow) {
      const from = line.slice(0, arrow.at).trim()
      let after = line.slice(arrow.at + arrow.spec.token.length)
      let text = ""
      const colon = after.indexOf(":")
      if (colon !== -1) {
        text = after.slice(colon + 1).trim()
        after = after.slice(0, colon)
      }
      let target = after.trim()
      let activateTarget = false
      let deactivateSource = false
      if (target.startsWith("+")) {
        activateTarget = true
        target = target.slice(1).trim()
      } else if (target.startsWith("-")) {
        deactivateSource = true
        target = target.slice(1).trim()
      }
      if (!from || !target) continue
      ensureParticipant(from)
      ensureParticipant(target)
      events.push({
        kind: "message",
        index: eventIndex++,
        from,
        to: target,
        text,
        line: arrow.spec.line,
        head: arrow.spec.head,
        self: from === target,
        activateTarget,
        deactivateSource,
      })
      continue
    }
    // Unknown line: ignore for resilience.
  }

  return { title, participants, boxes, events }
}

import { type Edge, type Node, Position } from "@xyflow/react"

import type { SeqModel, SequenceLayoutOptions } from "./types"

const ACTOR_W = 132
const ACTOR_H = 52
const MARGIN_X = 40
const MARGIN_TOP = 24
const BOX_LABEL_H = 26
const FIRST_MSG_OFFSET = 44
const SELF_H = 46
const NOTE_H = 44
const ACT_W = 10
const BOTTOM_GAP = 20

export interface HandleSpec {
  id: string
  type: "source" | "target"
  top: number
}

export interface SequenceGraph {
  nodes: Node[]
  edges: Edge[]
  width: number
  height: number
}

/** Convert a parsed model into positioned React Flow nodes and edges. */
export function buildSequenceGraph(
  model: SeqModel,
  options: SequenceLayoutOptions = {},
): SequenceGraph {
  const COL_GAP = options.columnGap ?? 220
  const MSG_GAP = options.messageGap ?? 56
  const showBottom = options.showBottomActors ?? true

  const index = new Map<string, number>()
  model.participants.forEach((p, i) => index.set(p.id, i))
  const xOf = (id: string) =>
    MARGIN_X + ACTOR_W / 2 + (index.get(id) ?? 0) * COL_GAP

  const hasBoxes = model.boxes.length > 0
  const headY = MARGIN_TOP + (hasBoxes ? BOX_LABEL_H : 0)
  const lifelineTop = headY + ACTOR_H

  const handles: Record<string, HandleSpec[]> = {}
  const addHandle = (
    pid: string,
    id: string,
    type: "source" | "target",
    absY: number,
  ) => {
    ;(handles[pid] ||= []).push({ id, type, top: absY - lifelineTop })
  }

  interface MsgLayout {
    index: number
    from: string
    to: string
    self: boolean
    data: Record<string, unknown>
  }
  const msgLayouts: MsgLayout[] = []

  interface ActBar {
    pid: string
    top: number
    height: number
    depth: number
  }
  const activations: ActBar[] = []
  const activeStacks: Record<string, { startY: number; depth: number }[]> = {}
  const pushAct = (pid: string, startY: number) => {
    const stack = (activeStacks[pid] ||= [])
    stack.push({ startY, depth: stack.length })
  }
  const popAct = (pid: string, endY: number) => {
    const stack = activeStacks[pid]
    if (!stack || stack.length === 0) return
    const s = stack.pop()!
    activations.push({
      pid,
      top: s.startY,
      height: Math.max(endY - s.startY, 18),
      depth: s.depth,
    })
  }

  interface NoteLayout {
    id: string
    x: number
    y: number
    width: number
    text: string
  }
  const notes: NoteLayout[] = []

  let y = lifelineTop + FIRST_MSG_OFFSET

  for (const ev of model.events) {
    if (ev.kind === "message") {
      const my = y
      if (ev.self) {
        const y2 = my + SELF_H
        addHandle(ev.from, `m${ev.index}-s`, "source", my)
        addHandle(ev.from, `m${ev.index}-t`, "target", y2)
        y = y2 + MSG_GAP
      } else {
        addHandle(ev.from, `m${ev.index}-s`, "source", my)
        addHandle(ev.to, `m${ev.index}-t`, "target", my)
        y = my + MSG_GAP
      }
      if (ev.activateTarget) pushAct(ev.to, my)
      if (ev.deactivateSource) popAct(ev.from, ev.self ? my + SELF_H : my)
      msgLayouts.push({
        index: ev.index,
        from: ev.from,
        to: ev.to,
        self: ev.self,
        data: {
          text: ev.text,
          line: ev.line,
          head: ev.head,
          self: ev.self,
          from: ev.from,
          to: ev.to,
        },
      })
    } else if (ev.kind === "note") {
      const ids = ev.participantIds
      let nx: number
      let nw: number
      if (ev.placement === "over") {
        const xs = ids.map(xOf)
        const min = Math.min(...xs)
        const max = Math.max(...xs)
        nw = ids.length > 1 ? max - min + ACTOR_W : 150
        nx = (min + max) / 2 - nw / 2
      } else if (ev.placement === "right") {
        nx = xOf(ids[0]) + 16
        nw = 150
      } else {
        nw = 150
        nx = xOf(ids[0]) - 16 - nw
      }
      notes.push({
        id: `note-${ev.index}`,
        x: nx,
        y,
        width: nw,
        text: ev.text,
      })
      y += NOTE_H + 20
    } else if (ev.kind === "activate") {
      pushAct(ev.participantId, y)
    } else if (ev.kind === "deactivate") {
      popAct(ev.participantId, y)
    }
  }

  // Close any activations left open.
  for (const pid of Object.keys(activeStacks)) {
    while (activeStacks[pid].length) popAct(pid, y)
  }

  const bottomHeadY = y + BOTTOM_GAP
  const lifelineHeight =
    (showBottom ? bottomHeadY : y + BOTTOM_GAP) - lifelineTop
  const height =
    (showBottom ? bottomHeadY + ACTOR_H : y + BOTTOM_GAP) + MARGIN_TOP
  const lastX = xOf(model.participants[model.participants.length - 1]?.id ?? "")
  const width = lastX + ACTOR_W / 2 + MARGIN_X

  const nodes: Node[] = []

  // Group boxes (lowest layer).
  for (const box of model.boxes) {
    if (box.participantIds.length === 0) continue
    const xs = box.participantIds.map(xOf)
    const left = Math.min(...xs) - ACTOR_W / 2 - 14
    const right = Math.max(...xs) + ACTOR_W / 2 + 14
    nodes.push({
      id: box.id,
      type: "seqGroup",
      position: { x: left, y: MARGIN_TOP },
      data: { label: box.label, width: right - left, height: height - MARGIN_TOP * 1.5 },
      draggable: false,
      selectable: false,
      zIndex: 0,
    })
  }

  // Lifelines.
  for (const p of model.participants) {
    nodes.push({
      id: `ll-${p.id}`,
      type: "seqLifeline",
      position: { x: xOf(p.id) - 1, y: lifelineTop },
      data: { participant: p.id, height: lifelineHeight, handles: handles[p.id] ?? [] },
      draggable: false,
      selectable: false,
      zIndex: 1,
    })
  }

  // Activation bars.
  activations.forEach((a, i) => {
    nodes.push({
      id: `act-${i}`,
      type: "seqActivation",
      position: { x: xOf(a.pid) - ACT_W / 2 + a.depth * 4, y: a.top },
      data: { participant: a.pid, height: a.height },
      draggable: false,
      selectable: false,
      zIndex: 3,
    })
  })

  // Actor heads (top + optional bottom).
  for (const p of model.participants) {
    nodes.push({
      id: `head-${p.id}`,
      type: "seqActor",
      position: { x: xOf(p.id) - ACTOR_W / 2, y: headY },
      data: { participant: p.id, label: p.label, actor: p.actor, width: ACTOR_W },
      draggable: false,
      selectable: false,
      zIndex: 5,
    })
    if (showBottom) {
      nodes.push({
        id: `head-b-${p.id}`,
        type: "seqActor",
        position: { x: xOf(p.id) - ACTOR_W / 2, y: bottomHeadY },
        data: { participant: p.id, label: p.label, actor: p.actor, width: ACTOR_W },
        draggable: false,
        selectable: false,
        zIndex: 5,
      })
    }
  }

  // Notes.
  for (const n of notes) {
    nodes.push({
      id: n.id,
      type: "seqNote",
      position: { x: n.x, y: n.y },
      data: { text: n.text, width: n.width, height: NOTE_H },
      draggable: false,
      selectable: false,
      zIndex: 6,
    })
  }

  // Message edges.
  const edges: Edge[] = msgLayouts.map((m) => ({
    id: `e${m.index}`,
    source: `ll-${m.from}`,
    sourceHandle: `m${m.index}-s`,
    target: `ll-${m.to}`,
    targetHandle: `m${m.index}-t`,
    type: "seqMessage",
    data: m.data,
    zIndex: 4,
  }))

  return { nodes, edges, width, height }
}

