"use client"

import { createContext, useContext } from "react"

export interface SequenceHoverState {
  hoveredEdge: string | null
  activeParticipants: Set<string>
  setHover: (edge: string | null, participants: string[]) => void
}

export const SequenceHoverContext = createContext<SequenceHoverState>({
  hoveredEdge: null,
  activeParticipants: new Set(),
  setHover: () => {},
})

export function useSequenceHover() {
  return useContext(SequenceHoverContext)
}

"use client"

import { Handle, type NodeProps, Position } from "@xyflow/react"
import { User } from "lucide-react"

import { cn } from "@/lib/utils"

import { useSequenceHover } from "./context"
import type { HandleSpec } from "./layout"

/** Grouping box drawn behind a set of participants. */
export function SeqGroupNode({ data }: NodeProps) {
  const d = data as { label: string; width: number; height: number }
  return (
    <div
      className="relative rounded-lg border border-dashed border-border bg-seq-group/40"
      style={{ width: d.width, height: d.height }}
    >
      {d.label ? (
        <span className="absolute left-2 top-2 rounded bg-card px-2 py-0.5 text-xs font-medium tracking-wide text-muted-foreground shadow-sm">
          {d.label}
        </span>
      ) : null}
    </div>
  )
}

/** Vertical dashed lifeline that hosts message handles. */
export function SeqLifelineNode({ data }: NodeProps) {
  const d = data as { participant: string; height: number; handles: HandleSpec[] }
  const { activeParticipants, hoveredEdge } = useSequenceHover()
  const active = activeParticipants.has(d.participant)
  return (
    <div style={{ width: 2, height: d.height }} className="relative">
      <div
        className={cn(
          "absolute left-1/2 top-0 h-full -translate-x-1/2 border-l border-dashed transition-colors",
          active ? "border-seq-accent" : "border-seq-lifeline/70",
        )}
        style={{ opacity: hoveredEdge && !active ? 0.4 : 1 }}
      />
      {d.handles.map((h) => (
        <Handle
          key={h.id}
          id={h.id}
          type={h.type}
          position={Position.Left}
          isConnectable={false}
          style={{
            top: h.top,
            left: 1,
            width: 1,
            height: 1,
            minWidth: 0,
            minHeight: 0,
            border: "none",
            background: "transparent",
            opacity: 0,
          }}
        />
      ))}
    </div>
  )
}

/** Activation bar overlaid on a lifeline. */
export function SeqActivationNode({ data }: NodeProps) {
  const d = data as { participant: string; height: number }
  const { activeParticipants, hoveredEdge } = useSequenceHover()
  const active = activeParticipants.has(d.participant)
  return (
    <div
      className={cn(
        "rounded-[2px] border transition-colors",
        active
          ? "border-seq-accent bg-seq-accent/25"
          : "border-seq-accent/40 bg-seq-activation",
      )}
      style={{ width: 10, height: d.height, opacity: hoveredEdge && !active ? 0.5 : 1 }}
    />
  )
}

/** Participant head box (or actor glyph). */
export function SeqActorNode({ data }: NodeProps) {
  const d = data as {
    participant: string
    label: string
    actor: boolean
    width: number
  }
  const { activeParticipants, hoveredEdge } = useSequenceHover()
  const active = activeParticipants.has(d.participant)
  return (
    <div
      className={cn(
        "flex h-[52px] items-center justify-center gap-2 rounded-md border bg-card px-3 text-center shadow-sm transition-colors",
        active ? "border-seq-accent ring-1 ring-seq-accent" : "border-border",
      )}
      style={{ width: d.width, opacity: hoveredEdge && !active ? 0.45 : 1 }}
    >
      {d.actor ? (
        <User className="size-4 shrink-0 text-muted-foreground" aria-hidden />
      ) : null}
      <span className="text-sm font-medium leading-tight text-card-foreground text-balance">
        {d.label}
      </span>
    </div>
  )
}

/** Note / badge callout. */
export function SeqNoteNode({ data }: NodeProps) {
  const d = data as { text: string; width: number; height: number }
  return (
    <div
      className="flex items-center justify-center rounded-sm border border-border bg-muted px-3 py-2 text-center text-xs leading-snug text-muted-foreground shadow-sm"
      style={{ width: d.width, minHeight: d.height }}
    >
      {d.text}
    </div>
  )
}

export const sequenceNodeTypes = {
  seqGroup: SeqGroupNode,
  seqLifeline: SeqLifelineNode,
  seqActivation: SeqActivationNode,
  seqActor: SeqActorNode,
  seqNote: SeqNoteNode,
}

"use client"

import { BaseEdge, EdgeLabelRenderer, type EdgeProps } from "@xyflow/react"

import { cn } from "@/lib/utils"

import { useSequenceHover } from "./context"
import type { ArrowHead, ArrowLine } from "./types"

const MARKER: Record<ArrowHead, string> = {
  filled: "url(#seq-arrow)",
  open: "url(#seq-arrow-open)",
  cross: "url(#seq-cross)",
  none: "",
}

interface MessageData {
  text: string
  line: ArrowLine
  head: ArrowHead
  self: boolean
  from: string
  to: string
}

export function SeqMessageEdge({
  id,
  sourceX,
  sourceY,
  targetX,
  targetY,
  data,
}: EdgeProps) {
  const d = data as unknown as MessageData
  const { hoveredEdge, setHover } = useSequenceHover()
  const hovered = hoveredEdge === id
  const dimmed = hoveredEdge !== null && !hovered

  let path: string
  let labelX: number
  let labelY: number

  if (d.self) {
    const loop = 62
    const x = sourceX
    path = `M ${x} ${sourceY} C ${x + loop} ${sourceY}, ${x + loop} ${targetY}, ${x} ${targetY}`
    labelX = x + loop
    labelY = (sourceY + targetY) / 2
  } else {
    path = `M ${sourceX} ${sourceY} L ${targetX} ${targetY}`
    labelX = (sourceX + targetX) / 2
    labelY = sourceY
  }

  const onEnter = () => setHover(id, [d.from, d.to])
  const onLeave = () => setHover(null, [])

  return (
    <>
      <BaseEdge
        id={id}
        path={path}
        markerEnd={MARKER[d.head]}
        interactionWidth={22}
        style={{
          stroke: "var(--seq-accent)",
          strokeWidth: hovered ? 2.5 : 1.5,
          strokeDasharray: d.line === "dashed" ? "6 4" : undefined,
          opacity: dimmed ? 0.35 : 1,
          transition: "opacity 120ms, stroke-width 120ms",
        }}
      />
      <EdgeLabelRenderer>
        {d.text ? (
          <div
            className={cn(
              "nodrag nopan pointer-events-auto absolute -translate-x-1/2 -translate-y-1/2 cursor-default rounded-md px-2 py-0.5 text-xs font-medium shadow-sm transition-all",
              "bg-seq-accent text-seq-accent-foreground",
              hovered && "ring-2 ring-seq-accent/40",
            )}
            style={{
              left: labelX,
              top: labelY,
              opacity: dimmed ? 0.4 : 1,
            }}
            onMouseEnter={onEnter}
            onMouseLeave={onLeave}
          >
            {d.text}
          </div>
        ) : null}
        {/* Invisible hit target over the line for hover when there is no label. */}
        <div
          className="nodrag nopan pointer-events-none absolute"
          style={{ left: labelX, top: labelY }}
        />
      </EdgeLabelRenderer>
      {/* Transparent wide path to capture hover along the whole line. */}
      <path
        d={path}
        fill="none"
        stroke="transparent"
        strokeWidth={22}
        style={{ pointerEvents: "stroke", cursor: "default" }}
        onMouseEnter={onEnter}
        onMouseLeave={onLeave}
      />
    </>
  )
}

export const sequenceEdgeTypes = {
  seqMessage: SeqMessageEdge,
}

"use client"

import "@xyflow/react/dist/base.css"

import { useMemo, useState } from "react"
import {
  Background,
  BackgroundVariant,
  Controls,
  ReactFlow,
  ReactFlowProvider,
} from "@xyflow/react"

import { cn } from "@/lib/utils"

import { SequenceHoverContext } from "./context"
import { sequenceEdgeTypes } from "./edges"
import { buildSequenceGraph } from "./layout"
import { sequenceNodeTypes } from "./nodes"
import { parseSequenceDiagram } from "./parser"
import type { SequenceLayoutOptions } from "./types"

export interface SequenceDiagramProps extends SequenceLayoutOptions {
  /** Mermaid-flavored sequence diagram definition. */
  chart: string
  className?: string
  /** Show the pan/zoom control bar. Defaults to true. */
  controls?: boolean
  /** Show the dotted background grid. Defaults to true. */
  background?: boolean
  /** Fit the diagram to the viewport on mount. Defaults to true. */
  fitView?: boolean
}

function MarkerDefs() {
  return (
    <svg width="0" height="0" className="absolute" aria-hidden focusable="false">
      <defs>
        <marker
          id="seq-arrow"
          markerWidth="12"
          markerHeight="12"
          refX="8"
          refY="4"
          orient="auto"
          markerUnits="userSpaceOnUse"
        >
          <path d="M0,0 L9,4 L0,8 z" fill="var(--seq-accent)" />
        </marker>
        <marker
          id="seq-arrow-open"
          markerWidth="12"
          markerHeight="12"
          refX="8"
          refY="4"
          orient="auto"
          markerUnits="userSpaceOnUse"
        >
          <path
            d="M0,0 L9,4 L0,8"
            fill="none"
            stroke="var(--seq-accent)"
            strokeWidth="1.5"
          />
        </marker>
        <marker
          id="seq-cross"
          markerWidth="12"
          markerHeight="12"
          refX="6"
          refY="4"
          orient="auto"
          markerUnits="userSpaceOnUse"
        >
          <path
            d="M1,1 L7,7 M7,1 L1,7"
            fill="none"
            stroke="var(--seq-accent)"
            strokeWidth="1.6"
          />
        </marker>
      </defs>
    </svg>
  )
}

function SequenceDiagramInner({
  chart,
  className,
  controls = true,
  background = true,
  fitView = true,
  columnGap,
  messageGap,
  showBottomActors,
}: SequenceDiagramProps) {
  const [hoveredEdge, setHoveredEdge] = useState<string | null>(null)
  const [activeParticipants, setActiveParticipants] = useState<Set<string>>(
    () => new Set(),
  )

  const { nodes, edges } = useMemo(() => {
    const model = parseSequenceDiagram(chart)
    return buildSequenceGraph(model, { columnGap, messageGap, showBottomActors })
  }, [chart, columnGap, messageGap, showBottomActors])

  const hoverValue = useMemo(
    () => ({
      hoveredEdge,
      activeParticipants,
      setHover: (edge: string | null, participants: string[]) => {
        setHoveredEdge(edge)
        setActiveParticipants(new Set(participants))
      },
    }),
    [hoveredEdge, activeParticipants],
  )

  return (
    <SequenceHoverContext.Provider value={hoverValue}>
      <div className={cn("relative size-full", className)}>
        <MarkerDefs />
        <ReactFlow
          nodes={nodes}
          edges={edges}
          nodeTypes={sequenceNodeTypes}
          edgeTypes={sequenceEdgeTypes}
          fitView={fitView}
          fitViewOptions={{ padding: 0.15 }}
          minZoom={0.2}
          maxZoom={2}
          proOptions={{ hideAttribution: false }}
          nodesDraggable={false}
          nodesConnectable={false}
          elementsSelectable={false}
          edgesFocusable={false}
          panOnScroll
          zoomOnScroll={false}
          className="bg-background"
        >
          {background ? (
            <Background
              variant={BackgroundVariant.Dots}
              gap={20}
              size={1}
              className="text-border"
            />
          ) : null}
          {controls ? <Controls showInteractive={false} /> : null}
        </ReactFlow>
      </div>
    </SequenceHoverContext.Provider>
  )
}

/**
 * A lightweight, read-only sequence diagram rendered with React Flow.
 * Author diagrams with Mermaid sequence-diagram syntax.
 */
export function SequenceDiagram(props: SequenceDiagramProps) {
  return (
    <ReactFlowProvider>
      <SequenceDiagramInner {...props} />
    </ReactFlowProvider>
  )
}
